-- Name: v_feishu_tbl_beta; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_feishu_tbl_beta AS
 WITH extracted AS (
         SELECT feishu_tbl_beta.id,
            feishu_tbl_beta.record_id,
            feishu_tbl_beta.fields,
            (feishu_tbl_beta.fields ->> '状态'::text) AS "审批状态",
            (feishu_tbl_beta.fields ->> '编号'::text) AS "编号",
            (feishu_tbl_beta.fields ->> '经营主体'::text) AS "集团",
            (feishu_tbl_beta.fields ->> '事业群'::text) AS "事业群",
            NULLIF((feishu_tbl_beta.fields ->> '行业部'::text), ''::text) AS "行业部",
            COALESCE(NULLIF((feishu_tbl_beta.fields ->> '业务承接角色'::text), ''::text), NULLIF((feishu_tbl_beta.fields ->> '细分业务'::text), ''::text)) AS "细分业务",
            (feishu_tbl_beta.fields ->> '层级级别'::text) AS "层级级别",
            (feishu_tbl_beta.fields ->> '任务承接人'::text) AS "负责人",
            (feishu_tbl_beta.fields ->> '任务维护人'::text) AS "上级负责人",
            (feishu_tbl_beta.fields ->> '链接字段(勿删)'::text) AS "组织路径",
            (feishu_tbl_beta.fields ->> '当前年'::text) AS "当前年",
            (feishu_tbl_beta.fields ->> '当前月'::text) AS "当前月"
           FROM public.feishu_tbl_beta
          WHERE ((feishu_tbl_beta.fields IS NOT NULL) AND (feishu_tbl_beta.fields <> '{}'::jsonb) AND (NULLIF((feishu_tbl_beta.fields ->> '编号'::text), ''::text) IS NOT NULL))
        )
 SELECT id,
    record_id,
    "审批状态",
    "编号",
    "集团",
    "事业群",
    "行业部",
    "细分业务",
    "层级级别",
    "负责人",
    "上级负责人",
    (COALESCE(NULLIF(regexp_replace((fields ->> '总任务（金额）'::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text), '0'::text))::numeric AS "年度目标营收",
    (COALESCE(NULLIF(regexp_replace((fields ->> '年度开单金额'::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text), '0'::text))::numeric AS "年度开单金额",
    (COALESCE(NULLIF(regexp_replace((fields ->> '总任务达成率'::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text), '0'::text))::numeric AS "总任务达成率",
    (COALESCE(NULLIF(regexp_replace((fields ->> '当前月份任务达成率'::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text), '0'::text))::numeric AS "当前月份任务达成率",
    (COALESCE(NULLIF(regexp_replace((fields ->> '截止当前目标阈值达成率'::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text), '0'::text))::numeric AS "截止当前目标阈值达成率",
    (COALESCE(NULLIF(regexp_replace((fields ->> '本月开单金额'::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text), '0'::text))::numeric AS "本月开单金额",
    (COALESCE(NULLIF(regexp_replace((fields ->> '本月当前目标阈值'::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text), '0'::text))::numeric AS "本月当前目标阈值",
    (COALESCE(NULLIF(regexp_replace((fields ->> '年度阈值/开单差额（万）'::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text), '0'::text))::numeric AS "年度阈值开单差额万",
    (COALESCE(NULLIF(regexp_replace((fields ->> '月度阈值/开单差额（万）'::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text), '0'::text))::numeric AS "月度阈值开单差额万",
    (COALESCE(NULLIF(regexp_replace((fields ->> '总金额转换（以万为单位）'::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text), '0'::text))::numeric AS "总金额转换万",
    (COALESCE(NULLIF(regexp_replace((fields ->> '年度开单金额转换（以万为单位）'::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text), '0'::text))::numeric AS "年度开单金额转换万",
    "组织路径",
    "当前年",
    "当前月",
    (COALESCE(NULLIF(regexp_replace((fields ->> '2601'::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text), '0'::text))::numeric AS "q1目标",
    (COALESCE(NULLIF(regexp_replace((fields ->> '2602'::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text), '0'::text))::numeric AS "q2目标",
    (COALESCE(NULLIF(regexp_replace((fields ->> '2603'::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text), '0'::text))::numeric AS "q3目标",
    (COALESCE(NULLIF(regexp_replace((fields ->> '2604'::text), '[^0-9.-]'::text, ''::text, 'g'::text), ''::text), '0'::text))::numeric AS "q4目标"
   FROM extracted;


