1668	3	detail	分析下衡原片区的业绩	WITH 汇总结果 AS (\nWITH raw_data AS (\n  SELECT TRIM(COALESCE(CASE WHEN jsonb_typeof(fields->'战区') = 'array' THEN fields->'战区'->0->>'text' ELSE fields->>'战区' END,\n        '')) AS 战区,\n    TRIM(COALESCE(CASE WHEN jsonb_typeof(fields->'片区') = 'array' THEN fields->'片区'->0->>'text' ELSE fields->>'片区' END,\n        '')) AS 片区,\n    TRIM(COALESCE(CASE WHEN jsonb_typeof(fields->'客户经理') = 'array' THEN fields->'客户经理'->0->>'text' ELSE fields->>'客户经理' END,\n        '')) AS 客户经理,\n    '' AS 行业部,\n    SUM(COALESCE(NULLIF(regexp_replace(COALESCE(CASE WHEN jsonb_typeof(fields->'总任务（金额）') = 'array' THEN fields->'总任务（金额）'->0->>'text' ELSE fields->>'总任务（金额）' END,\n              '0'),\n            '[^0-9.-]',\n            '',\n            'g'),\n          ''),\n        '0')::NUMERIC) AS 总任务金额,\n    SUM(COALESCE(NULLIF(regexp_replace(COALESCE(CASE WHEN jsonb_typeof(fields->'年度开单金额') = 'array' THEN fields->'年度开单金额'->0->>'text' ELSE fields->>'年度开单金额' END,\n              '0'),\n            '[^0-9.-]',\n            '',\n            'g'),\n          ''),\n        '0')::NUMERIC) AS 年度开单金额\n  FROM datapivot_core_data\n  WHERE COALESCE(NULLIF(TRIM(CASE WHEN jsonb_typeof(fields->'当前年') = 'array' THEN fields->'当前年'->0->>'text' ELSE fields->>'当前年' END),\n        ''),\n      '2026') = '2026'\n  GROUP BY 1,\n    2,\n    3,\n    4 ),\n  flattened_tree AS (\n  SELECT CASE WHEN 客户经理 <> '' THEN '客户经理' WHEN 片区 <> '' THEN '片区' WHEN 战区 <> ''\n    AND 战区 LIKE '%行业部' THEN '行业部' WHEN 行业部 <> '' THEN '行业部' WHEN 战区 <> '' THEN '战区' ELSE '事业群' END AS 层级,\n    CASE WHEN 客户经理 <> '' THEN COALESCE(NULLIF(片区,\n        ''),\n      NULLIF(行业部,\n        ''),\n      NULLIF(战区,\n        ''),\n      '商用事业群') WHEN 片区 <> '' THEN NULLIF(战区,\n      '') WHEN 战区 <> ''\n    OR 行业部 <> '' THEN '商用事业群' ELSE NULL END AS 上级名称,\n    CASE WHEN 客户经理 <> '' THEN 客户经理 WHEN 片区 <> '' THEN 片区 WHEN 战区 <> '' THEN 战区 WHEN 行业部 <> '' THEN 行业部 ELSE '商用事业群' END AS 节点名称,\n    CASE WHEN COALESCE(NULLIF(战区,\n        ''),\n      NULLIF(行业部,\n      '')) LIKE '%行业部' THEN '行业线' WHEN COALESCE(NULLIF(战区,\n        ''),\n      NULLIF(行业部,\n        '')) LIKE '%战区' THEN '区域线' ELSE '事业群层级' END AS 线,\n    总任务金额,\n    年度开单金额\n  FROM raw_data ),\n  summarized_nodes AS (\n  SELECT 线,\n    层级,\n    上级名称,\n    节点名称,\n    SUM(总任务金额) AS 总任务金额,\n    SUM(年度开单金额) AS 年度开单金额\n  FROM flattened_tree\n  WHERE 节点名称 <> ''\n  GROUP BY 线,\n    层级,\n    上级名称,\n    节点名称 )\nSELECT 线,\n  层级,\n  节点名称,\n  上级名称,\n  总任务金额,\n  年度开单金额,\n  CASE WHEN 总任务金额 = 0 THEN 0 ELSE ROUND((年度开单金额 / 总任务金额) * 100,\n    2) END AS 达成率,\n  ROUND(总任务金额 - 年度开单金额,\n    2) AS 剩余任务金额\nFROM summarized_nodes ),\n命中节点 AS (\nSELECT 节点名称\nFROM 汇总结果\nWHERE 节点名称 LIKE '%片区%'\n   OR 上级名称 LIKE '%片区%'\n),\n命中孙级 AS (\nSELECT 子节点.节点名称\nFROM 汇总结果 子节点\nWHERE 子节点.上级名称 IN (\n  SELECT 节点名称\n  FROM 命中节点)\n)\nSELECT *\nFROM 汇总结果\nWHERE 节点名称 LIKE '%片区%'\n   OR 上级名称 LIKE '%片区%'\n   OR 节点名称 IN (SELECT 节点名称 FROM 命中孙级)\nORDER BY 线 DESC,\n层级 DESC,\n上级名称,\n节点名称\nLIMIT 10000	[]	89	0	\N	t	ui	2026-06-27 20:03:29.129775+08	2026-06-27 20:03:29.129775+08
986	63	mom	泠州片区今年前六个月大盘开单的环比增速轨迹	SELECT 月份, SUM(年度开单金额) AS 当月销售, LAG(SUM(年度开单金额)) OVER (ORDER BY 月份) AS 上月销售, CASE WHEN LAG(SUM(年度开单金额)) OVER (ORDER BY 月份) > 0 THEN ROUND((SUM(年度开单金额) - LAG(SUM(年度开单金额)) OVER (ORDER BY 月份)) / LAG(SUM(年度开单金额)) OVER (ORDER BY 月份) * 100, 2) ELSE 0 END AS 环比增长 FROM public.v_feishu_tbl_gamma_v2 WHERE 节点名称 = '泠州片区' AND 层级 = '片区' AND 行业线 = '总额(未拆分)' AND 年份 = '2026' AND 月份 BETWEEN 1 AND 6 GROUP BY 月份 ORDER BY 月份;	["环比", "片区", "月度趋势"]	99	0	\N	t	ui	2026-06-26 15:37:03.976592+08	2026-06-26 15:37:03.976592+08
995	63	audit	珩京片区的官方大盘指标和派下去的客户经理指标总和有没有未分派指标	WITH office_budget AS (SELECT SUM(总任务金额) AS o_target FROM public.v_feishu_tbl_gamma_v2 WHERE 节点名称 = '珩京片区' AND 层级 = '片区' AND 行业线 = '总额(未拆分)' AND 年份 = '2026'), reps_budget AS (SELECT SUM(总任务金额) AS r_target FROM public.v_feishu_tbl_gamma_v2 WHERE 上级名称 = '珩京片区' AND 层级 = '客户经理' AND 行业线 = '总额(未拆分)' AND 年份 = '2026') SELECT o_target AS 片区总预算, r_target AS 下属分发总预算, (o_target - r_target) AS 未分配预留额度 FROM office_budget, reps_budget;	["对账", "片区", "合规分析"]	98	0	\N	t	ui	2026-06-26 15:37:03.976592+08	2026-06-26 15:37:03.976592+08
