 NULLIF(行业部,\n        '')) LIKE '%行业部' THEN '行业线' WHEN COALESCE(NULLIF(战区,\n        ''),\n      NULLIF(行业部,\n        '')) LIKE '%战区' THEN '区域线' ELSE '事业群层级' END AS 线,\n    总任务金额,\n    年度开单金额\n  FROM raw_data ),\n  summarized_nodes AS (\n  SELECT 线,\n    层级,\n    上级名称,\n    节点名称,\n    SUM(总任务金额) AS 总任务金额,\n    SUM(年度开单金额) AS 年度开单金额\n  FROM flattened_tree\n  WHERE 节点名称 <> ''\n  GROUP BY 线,\n    层级,\n    上级名称,\n    节点名称 )\nSELECT 线,\n  层级,\n  节点名称,\n  上级名称,\n  总任务金额,\n  年度开单金额,\n  CASE WHEN 总任务金额 = 0 THEN 0 ELSE ROUND((年度开单金额 / 总任务金额) * 100,\n    2) END AS 达成率,\n  ROUND(总任务金额 - 年度开单金额,\n    2) AS 剩余任务金额\nFROM summarized_nodes ),\n命中节点 AS (\nSELECT 节点名称\nFROM 汇总结果\nWHERE 节点名称 IN ('商用事业群')\n  OR 上级名称 IN ('商用事业群') ),\n命中孙级 AS (\nSELECT 子节点.节点名称\nFROM 汇总结果 子节点\nWHERE 子节点.上级名称 IN (\n  SELECT 节点名称\n  FROM 命中节点) )\nSELECT *\nFROM 汇总结果\nWHERE 节点名称 IN ('商用事业群')\n  OR 上级名称 IN ('商用事业群')\n  OR 节点名称 IN (\nSELECT 节点名称\nFROM 命中孙级)\nORDER BY 线 DESC,\n层级 DESC,\n上级名称,\n节点名称\nLIMIT 10000	["phase1", "summary", "verified_candidate"]	92	0	\N	t	ui	2026-06-27 20:03:29.129775+08	2026-06-27 20:03:29.129775+08
2628	2	risk	哪个战区低于30%？	WITH 源数据 AS (\n  SELECT\n    fields,\n    COALESCE(NULLIF(regexp_replace(fields ->> '总任务（金额）', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 总任务原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '年度开单金额', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 年度开单原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '线下', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 线下任务原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '线下-年度开单金额', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 线下实际原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '新零售', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 新零售任务原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '新零售-年度开单金额', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 新零售实际原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '燃气定制', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 燃气定制任务原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '燃气定制-年度开单金额', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 燃气定制实际原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '地产', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 地产任务原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '地产-年度开单金额', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 地产实际原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '总任务达成率', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 达成率原值\n  FROM public.feishu_tbl_alpha\n),\n标准结果 AS (\n  SELECT\n    '消费者事业群' AS 线,\n    CASE\n      WHEN NULLIF(fields ->> '战区', '') IS NULL THEN '消费者事业群总体'\n      WHEN NULLIF(fields ->> '城市战区', '') IS NULL THEN '战区'\n      ELSE '城市战区'\n    END AS 层级,\n    CASE\n      WHEN NULLIF(fields ->> '战区', '') IS NULL THEN '消费者事业群'\n      WHEN NULLIF(fields ->> '城市战区', '') IS NULL THEN fields ->> '战区'\n      ELSE fields ->> '城市战区'\n    END AS 节点名称,\n    CASE\n      WHEN NULLIF(fields ->> '战区', '') IS NULL THEN NULL\n      WHEN NULLIF(fields ->> '城市战区', '') IS NULL THEN '消费者事业群'\n      ELSE fields ->> '战区'\n    END AS 上级名称,\n    ROUND(总任务原值, 2) AS 总任务金额,\n    ROUND(年度开单原值, 2) AS 年度开单金额,\n    ROUND(CASE WHEN 总任务原值 > 0 THEN 年度开单原值 / 总任务原值 * 100 ELSE 达成率原值 END, 2) AS 达成率,\n    ROUND(GREATEST(总任务原值 - 年度开单原值, 0), 2) AS 剩余任务金额,\n    ROUND(线下任务原值, 2) AS 线下任务金额,\n    ROUND(线下实际原值, 2) AS 线下开单金额,\n    ROUND(新零售任务原值, 2) AS 新零售任务金额,\n    ROUND(新零售实际原值, 2) AS 新零售开单金额,\n    ROUND(燃气定制任务原值, 2) AS 燃气定制任务金额,\n    ROUND(燃气定制实际原值, 2) AS 燃气定制开单金额,\n    ROUND(地产任务原值, 2) AS 地产任务金额,\n    ROUND(地产实际原值, 2) AS 地产开单金额\n  FROM 源数据\n  WHERE 总任务原值 > 0\n)\nSELECT *\nFROM 标准结果\nWHERE 层级 = '战区'\n  AND 达成率 < 30\nORDER BY 达成率 ASC, 剩余任务金额 DESC, 节点名称\nLIMIT 200;	["风险节点", "战区"]	95	0	\N	t	ui	2026-07-08 15:41:23.865975+08	2026-07-08 15:41:23.865975+08
987	63	ratio	澔原最厉害的那两个销售占了澔原大半业绩吧，算下他们上半年占了多少比例	WITH branch_total AS (SELECT SUM(年度开单金额) AS b_total FROM public.v_feishu_tbl_gamma_v2 WHERE 节点名称 = '澔原战区' AND 层级 = '战区' AND 行业线 = '总额(未拆分)' AND 年份 = '2026' AND 月份 BETWEEN 1 AND 6), top_reps AS (SELECT 节点名称, SUM(年度开单金额) AS rep_billing FROM public.v_feishu_tbl_gamma_v2 WHERE 层级 = '客户经理' AND 行业线 = '总额(未拆分)' AND 年份 = '2026' AND 月份 BETWEEN 1 AND 6 AND 上级名称 IN (SELECT 节点名称 FROM public.v_feishu_tbl_gamma_v2 WHERE 上级名称 = '澔原战区' AND 层级 = '片区' AND 行业线 = '总额(未拆分)' AND 年份 = '2026') GROUP BY 节点名称 ORDER BY rep_billing DESC LIMIT 2), reps_sum AS (SELECT SUM(rep_billing) AS r_sum FROM top_reps) SELECT b.b_total AS 澔原上半年销售额, r.r_sum AS 核心客户经理销售和, CASE WHEN b.b_total > 0 THEN ROUND(r.r_sum / b.b_total * 100, 2) ELSE 0 END AS 业绩占比 FROM branch_total b, reps_sum r;	["占比", "客户经理", "帕累托分析"]	99	0	\N	t	ui	2026-06-26 15:37:03.976592+08	2026-06-26 15:37:03.976592+08
988	63	yoy	对比今年上半年各区域战区的官方大盘总开单以及相比去年的同比增速	SELECT 节点名称 AS 战区, SUM(年度开单金额) AS 今年上半年销售, SUM(去年同期开单) AS 去年上半年销售, CASE WHEN SUM(去年同期开单) > 0 THEN ROUND((SUM(年度开单金额) - SUM(去年同期开单)) / SUM(去年同期开单) * 100, 2) ELSE 0 END AS 同比增速 FROM public.v_feishu_tbl_gamma_v2 WHERE 层级 = '战区' AND 线 = '区域线' AND 行业线 = '总额(未拆分)' AND 年份 = '2026' AND 月份 BETWEEN 1 AND 6 GROUP BY 节点名称 ORDER BY 同比增速 DESC;	["同比", "战区", "上半年"]	99	0	\N	t	ui	2026-06-26 15:37:03.976592+08	2026-06-26 15:37:03.976592+08
