    NULLIF(行业部,\n        '')) LIKE '%行业部' THEN '行业线' WHEN COALESCE(NULLIF(战区,\n        ''),\n      NULLIF(行业部,\n        '')) LIKE '%战区' THEN '区域线' ELSE '事业群层级' END AS 线,\n    总任务金额,\n    年度开单金额\n  FROM raw_data ),\n  summarized_nodes AS (\n  SELECT 线,\n    层级,\n    上级名称,\n    节点名称,\n    SUM(总任务金额) AS 总任务金额,\n    SUM(年度开单金额) AS 年度开单金额\n  FROM flattened_tree\n  WHERE 节点名称 <> ''\n  GROUP BY 线,\n    层级,\n    上级名称,\n    节点名称 )\nSELECT 线,\n  层级,\n  节点名称,\n  上级名称,\n  总任务金额,\n  年度开单金额,\n  CASE WHEN 总任务金额 = 0 THEN 0 ELSE ROUND((年度开单金额 / 总任务金额) * 100,\n    2) END AS 达成率,\n  ROUND(总任务金额 - 年度开单金额,\n    2) AS 剩余任务金额\nFROM summarized_nodes )\n\n-- 这里只查【某个业务员】\nSELECT *\nFROM 汇总结果\nWHERE 层级 = '客户经理' \n  AND 节点名称 = '殷怀川'  -- 把张三改成你要查的业务员名字\nORDER BY 节点名称	[]	80	0	\N	t	ui	2026-06-27 20:03:29.129775+08	2026-06-27 20:03:29.129775+08
990	63	ratio	岚屿战区旗下所有客户经理今年食饮板块销售占他们个人总开单的比例大PK	WITH rep_segment_data AS (SELECT 节点名称 AS 客户经理, SUM(CASE WHEN 行业线 = '食饮部' THEN 年度开单金额 ELSE 0 END) AS 食饮销售, SUM(CASE WHEN 行业线 = '总额(未拆分)' THEN 年度开单金额 ELSE 0 END) AS 个人总销售 FROM public.v_feishu_tbl_gamma_v2 WHERE 层级 = '客户经理' AND 年份 = '2026' AND 上级名称 IN (SELECT 节点名称 FROM public.v_feishu_tbl_gamma_v2 WHERE 上级名称 = '岚屿战区' AND 层级 = '片区' AND 行业线 = '总额(未拆分)' AND 年份 = '2026') GROUP BY 节点名称) SELECT 客户经理, 个人总销售 AS 年度累计开单, 食饮销售 AS 食饮开单, CASE WHEN 个人总销售 > 0 THEN ROUND(食饮销售 / 个人总销售 * 100, 2) ELSE 0 END AS 食饮开单占比 FROM rep_segment_data ORDER BY 食饮开单占比 DESC;	["占比", "客户经理", "贡献度对比"]	99	0	\N	t	ui	2026-06-26 15:37:03.976592+08	2026-06-26 15:37:03.976592+08
991	63	ratio	云梦和越溪一季度业绩占了整个澔原的多少比例	WITH branch_total AS (SELECT SUM(年度开单金额) AS b_billing FROM public.v_feishu_tbl_gamma_v2 WHERE 节点名称 = '澔原战区' AND 层级 = '战区' AND 行业线 = '总额(未拆分)' AND 年份 = '2026' AND 月份 BETWEEN 1 AND 3), office_totals AS (SELECT 节点名称 AS office_name, SUM(年度开单金额) AS o_billing FROM public.v_feishu_tbl_gamma_v2 WHERE 节点名称 IN ('云栖片区', '越溪片区') AND 层级 = '片区' AND 行业线 = '总额(未拆分)' AND 年份 = '2026' AND 月份 BETWEEN 1 AND 3 GROUP BY 节点名称) SELECT o.office_name, o.o_billing, b.b_billing, CASE WHEN b.b_billing > 0 THEN ROUND(o.o_billing / b.b_billing * 100, 2) ELSE 0 END AS 贡献占比 FROM office_totals o, branch_total b;	["占比", "片区", "业绩贡献"]	99	0	\N	t	ui	2026-06-26 15:37:03.976592+08	2026-06-26 15:37:03.976592+08
1008	13	aggregation	消费者事业群整体达成率是多少	SELECT\n -- 1. 层级结构\n CASE\n WHEN fields ->> '战区' IS NULL OR fields ->> '战区' = '' THEN '消费者事业群总体'\n WHEN fields ->> '城市战区' IS NULL OR fields ->> '城市战区' = '' THEN '战区'\n ELSE '城市战区'\n END AS 层级,\n\n CASE\n WHEN fields ->> '战区' IS NULL OR fields ->> '战区' = '' THEN '消费者事业群'\n WHEN fields ->> '城市战区' IS NULL OR fields ->> '城市战区' = '' THEN fields ->> '战区'\n ELSE fields ->> '城市战区'\n END AS 节点名称,\n\n CASE\n WHEN fields ->> '战区' IS NULL OR fields ->> '战区' = '' THEN NULL\n WHEN fields ->> '城市战区' IS NULL OR fields ->> '城市战区' = '' THEN '消费者事业群'\n ELSE fields ->> '战区'\n END AS 上级名称,\n\n-- 2. 总目标、总实际、总达成率 ✅ 达成率 ×100\n ROUND(COALESCE((fields ->> '总任务（金额）')::NUMERIC, 0) / 10000, 2) AS 总任务_万元,\n ROUND(COALESCE((fields ->> '年度开单金额')::NUMERIC, 0) / 10000, 2) AS 总实际_万元,\n ROUND(COALESCE((fields ->> '总任务达成率')::NUMERIC, 0) * 100, 2) AS 总达成率,  -- 这里 ×100\n\n-- 3. 4条业务线 —— 任务\n ROUND(COALESCE((fields ->> '线下')::NUMERIC, 0) / 10000, 2) AS 线下任务_万元,\n ROUND(COALESCE((fields ->> '新零售')::NUMERIC, 0) / 10000, 2) AS 新零售任务_万元,\n ROUND(COALESCE((fields ->> '燃气定制')::NUMERIC, 0) / 10000, 2) AS 燃气定制任务_万元,\n ROUND(COALESCE((fields ->> '地产')::NUMERIC, 0) / 10000, 2) AS 地产任务_万元,\n\n-- 4. 4条业务线 —— 实际开单\n ROUND(COALESCE((fields ->> '线下-年度开单金额')::NUMERIC, 0) / 10000, 2) AS 线下实际_万元,\n ROUND(COALESCE((fields ->> '新零售-年度开单金额')::NUMERIC, 0) / 10000, 2) AS 新零售实际_万元,\n ROUND(COALESCE((fields ->> '燃气定制-年度开单金额')::NUMERIC, 0) / 10000, 2) AS 燃气定制实际_万元,\n ROUND(COALESCE((fields ->> '地产-年度开单金额')::NUMERIC, 0) / 10000, 2) AS 地产实际_万元\n\nFROM public.feishu_tbl_alpha\n\nORDER BY\n CASE\n WHEN fields ->> '战区' IS NULL OR fields ->> '战区' = '' THEN 1\n WHEN fields ->> '城市战区' IS NULL OR fields ->> '城市战区' = '' THEN 2\n ELSE 3\n END,\n 节点名称;	["整体汇总", "达成率"]	95	0	\N	t	ui	2026-06-26 15:37:11.907836+08	2026-06-26 15:37:11.907836+08
2629	2	comparative	四条业务线贡献如何？	WITH 源数据 AS (\n  SELECT\n    fields,\n    COALESCE(NULLIF(regexp_replace(fields ->> '总任务（金额）', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 总任务原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '年度开单金额', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 年度开单原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '线下', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 线下任务原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '线下-年度开单金额', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 线下实际原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '新零售', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 新零售任务原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '新零售-年度开单金额', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 新零售实际原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '燃气定制', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 燃气定制任务原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '燃气定制-年度开单金额', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 燃气定制实际原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '地产', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 地产任务原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '地产-年度开单金额', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 地产实际原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '总任务达成率', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 达成率原值\n  FROM public.feishu_tbl_alpha\n),\n标准结果 AS (\n  SELECT\n    '消费者事业群' AS 线,\n    CASE\n      WHEN NULLIF(fields ->> '战区', '') IS NULL THEN '消费者事业群总体'\n      WHEN NULLIF(fields ->> '城市战区', '') IS NULL THEN '战区'\n      ELSE '城市战区'\n    END AS 层级,\n    CASE\n      WHEN NULLIF(fields ->> '战区', '') IS NULL THEN '消费者事业群'\n      WHEN NULLIF(fields ->> '城市战区', '') IS NULL THEN fields ->> '战区'\n      ELSE fields ->> '城市战区'\n    END AS 节点名称,\n    CASE\n      WHEN NULLIF(fields ->> '战区', '') IS NULL THEN NULL\n      WHEN NULLIF(fields ->> '城市战区', '') IS NULL THEN '消费者事业群'\n      ELSE fields ->> '战区'\n    END AS 上级名称,\n    ROUND(总任务原值, 2) AS 总任务金额,\n    ROUND(年度开单原值, 2) AS 年度开单金额,\n    ROUND(CASE WHEN 总任务原值 > 0 THEN 年度开单原值 / 总任务原值 * 100 ELSE 达成率原值 END, 2) AS 达成率,\n    ROUND(GREATEST(总任务原值 - 年度开单原值, 0), 2) AS 剩余任务金额,\n    ROUND(线下任务原值, 2) AS 线下任务金额,\n    ROUND(线下实际原值, 2) AS 线下开单金额,\n    ROUND(新零售任务原值, 2) AS 新零售任务金额,\n    ROUND(新零售实际原值, 2) AS 新零售开单金额,\n    ROUND(燃气定制任务原值, 2) AS 燃气定制任务金额,\n    ROUND(燃气定制实际原值, 2) AS 燃气定制开单金额,\n    ROUND(地产任务原值, 2) AS 地产任务金额,\n    ROUND(地产实际原值, 2) AS 地产开单金额\n  FROM 源数据\n  WHERE 总任务原值 > 0\n)\nSELECT\n  节点名称,\n  业务线,\n  任务金额,\n  开单金额,\n  ROUND(CASE WHEN 任务金额 > 0 THEN 开单金额 / 任务金额 * 100 ELSE 0 END, 2) AS 达成率\nFROM 标准结果\nCROSS JOIN LATERAL (\n  VALUES\n    ('线下', 线下任务金额, 线下开单金额),\n    ('新零售', 新零售任务金额, 新零售开单金额),\n    ('燃气定制', 燃气定制任务金额, 燃气定制开单金额),\n    ('地产', 地产任务金额, 地产开单金额)\n) AS 业务线明细(业务线, 任务金额, 开单金额)\nWHERE 层级 = '消费者事业群总体'\nORDER BY 开单金额 DESC;	["业务线", "贡献度"]	95	0	\N	t	ui	2026-07-08 15:41:23.865975+08	2026-07-08 15:41:23.865975+08
