165	63	v_feishu_tbl_gamma_v2	CREATE OR REPLACE VIEW public.v_feishu_tbl_gamma_v2 AS\nWITH parsed_base AS (\n    SELECT \n      COALESCE(NULLIF(regexp_replace(fields->>'MYear', '[^0-9]', '', 'g'), ''), '0')::INTEGER AS current_year,\n      COALESCE(NULLIF(regexp_replace(fields->>'MMonth', '[^0-9]', '', 'g'), ''), '0')::INTEGER AS current_month,\n      COALESCE(fields->>'AreaName', '') AS f_area,\n      COALESCE(fields->>'RegionName', '') AS f_region,\n      COALESCE(fields->>'BusinessManager', '') AS f_manager,\n      COALESCE(fields->>'IndustryLine', '') AS f_industry,\n      COALESCE(NULLIF(regexp_replace(fields->>'TargetAmount', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS target_amount,\n      COALESCE(NULLIF(regexp_replace(fields->>'SellInAmount', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS billing_amount,\n      COALESCE(NULLIF(regexp_replace(fields->>'SellInAmount_LastYear', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS billing_last_year\n    FROM public.feishu_tbl_gamma_v2\n)\nSELECT \n  current_year AS 年份,\n  current_month AS 月份,\n  CASE \n    WHEN f_area = '' AND f_region = '' AND f_manager = '' THEN '事业群层级'\n    WHEN f_area LIKE '%战区' THEN '区域线'\n    WHEN f_area LIKE '%行业部' THEN '行业线'\n    ELSE '区域线'\n  END AS 线,\n  CASE \n    WHEN f_area = '' AND f_region = '' AND f_manager = '' THEN '事业群'\n    WHEN f_area <> '' AND f_region = '' AND f_manager = '' THEN '战区'\n    WHEN f_area <> '' AND f_region <> '' AND f_manager = '' THEN '片区'\n    WHEN f_area <> '' AND f_manager <> '' THEN '客户经理'\n    ELSE '未知'\n  END AS 层级,\n  CASE \n    WHEN f_area = '' AND f_region = '' AND f_manager = '' THEN '商用事业群'\n    WHEN f_area <> '' AND f_region = '' AND f_manager = '' THEN f_area\n    WHEN f_area <> '' AND f_region <> '' AND f_manager = '' THEN f_region\n    WHEN f_area <> '' AND f_manager <> '' THEN f_manager\n    ELSE '未知'\n  END AS 节点名称,\n  CASE \n    WHEN f_area = '' AND f_region = '' AND f_manager = '' THEN '无'\n    WHEN f_area <> '' AND f_region = '' AND f_manager = '' THEN '商用事业群'\n    WHEN f_area <> '' AND f_region <> '' AND f_manager = '' THEN f_area\n    WHEN f_area <> '' AND f_region <> '' AND f_manager <> '' THEN f_region\n    WHEN f_area <> '' AND f_region = '' AND f_manager <> '' THEN f_area\n    ELSE '无'\n  END AS 上级名称,\n  CASE \n    WHEN f_industry = '' THEN '总额(未拆分)'\n    ELSE f_industry\n  END AS 行业线,\n  target_amount AS 总任务金额,\n  billing_amount AS 年度开单金额,\n  billing_last_year AS 去年同期开单,\n  CASE WHEN target_amount > 0 THEN ROUND(billing_amount / target_amount * 100, 2) ELSE 0 END AS 达成率,\n  ROUND(target_amount - billing_amount, 2) AS 剩余任务金额\nFROM parsed_base;	商用事业群月度经营分析关系型中文标准视图（支持物理层防零除转换和数值规范）	t	2026-06-26 15:37:03.976592+08	2026-06-26 15:37:03.976592+08	1
