"", "事业群": "商用事业群", "行业部": "", "达成率": 123.26, "上级名称": "商用事业群", "客户经理": "", "节点名称": "工业健康行业部", "总任务金额": 10000000.0, "剩余任务金额": -2325511.73, "年度开单金额": 12325511.73}, {"线": "区域线", "层级": "战区", "战区": "澔原战区", "片区": "", "事业群": "商用事业群", "行业部": "", "达成率": 45.47, "上级名称": "商用事业群", "客户经理": "", "节点名称": "澔原战区", "总任务金额": 91175420.0, "剩余任务金额": 49720980.47, "年度开单金额": 41454439.528247}, {"线": "区域线", "层级": "战区", "战区": "岚屿战区", "片区": "", "事业群": "商用事业群", "行业部": "", "达成率": 43.96, "上级名称": "商用事业群", "客户经理": "", "节点名称": "岚屿战区", "总任务金额": 80821559.0, "剩余任务金额": 45290527.54, "年度开单金额": 35531031.457365}, {"线": "行业线", "层级": "行业部", "战区": "食饮行业部", "片区": "", "事业群": "商用事业群", "行业部": "", "达成率": 43.15, "上级名称": "商用事业群", "客户经理": "", "节点名称": "食饮行业部", "总任务金额": 105000000.0, "剩余任务金额": 59697481.08, "年度开单金额": 45302518.92}, {"线": "区域线", "层级": "战区", "战区": "瀚川战区", "片区": "", "事业群": "商用事业群", "行业部": "", "达成率": 41.15, "上级名称": "商用事业群", "客户经理": "", "节点名称": "瀚川战区", "总任务金额": 56861650.0, "剩余任务金额": 33465124.18, "年度开单金额": 23396525.824099}, {"线": "区域线", "层级": "战区", "战区": "朔岑战区", "片区": "", "事业群": "商用事业群", "行业部": "", "达成率": 38.41, "上级名称": "商用事业群", "客户经理": "", "节点名称": "朔岑战区", "总任务金额": 69943354.0, "剩余任务金额": 43074766.02, "年度开单金额": 26868587.976464}], "total_tokens": 835, "original_error": "", "dataset_results": [{"sql": "SELECT * FROM (\\nWITH 汇总结果 AS (\\nWITH raw_data AS (\\n    SELECT\\n        TRIM(COALESCE(CASE WHEN jsonb_typeof(fields->'战区') = 'array' THEN fields->'战区'->0->>'text' ELSE fields->>'战区' END, '')) AS 战区,\\n        TRIM(COALESCE(CASE WHEN jsonb_typeof(fields->'片区') = 'array' THEN fields->'片区'->0->>'text' ELSE fields->>'片区' END, '')) AS 片区,\\n        TRIM(COALESCE(CASE WHEN jsonb_typeof(fields->'客户经理') = 'array' THEN fields->'客户经理'->0->>'text' ELSE fields->>'客户经理' END, '')) AS 客户经理,\\n        '' AS 行业部,\\n        SUM(COALESCE(NULLIF(regexp_replace(COALESCE(CASE WHEN jsonb_typeof(fields->'总任务（金额）') = 'array' THEN fields->'总任务（金额）'->0->>'text' ELSE fields->>'总任务（金额）' END, '0'), '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC) AS 总任务金额,\\n        SUM(COALESCE(NULLIF(regexp_replace(COALESCE(CASE WHEN jsonb_typeof(fields->'年度开单金额') = 'array' THEN fields->'年度开单金额'->0->>'text' ELSE fields->>'年度开单金额' END, '0'), '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC) AS 年度开单金额\\n    FROM datapivot_core_data\\n    WHERE COALESCE(NULLIF(TRIM(CASE WHEN jsonb_typeof(fields->'当前年') = 'array' THEN fields->'当前年'->0->>'text' ELSE fields->>'当前年' END), ''), '2026') = '2026'\\n    GROUP BY 1, 2, 3, 4\\n),\\nflattened_tree AS (\\n    SELECT\\n        CASE\\n            WHEN 客户经理 <> '' THEN '客户经理'\\n            WHEN 片区 <> '' THEN '片区'\\n            WHEN 战区 <> '' AND 战区 LIKE '%行业部' THEN '行业部'\\n            WHEN 行业部 <> '' THEN '行业部'\\n            WHEN 战区 <> '' THEN '战区'\\n            ELSE '事业群'\\n        END AS 层级,\\n        CASE\\n            WHEN 客户经理 <> '' THEN COALESCE(NULLIF(片区, ''), NULLIF(行业部, ''), NULLIF(战区, ''), '商用事业群')\\n            WHEN 片区 <> '' THEN NULLIF(战区, '')\\n            WHEN 战区 <> '' OR 行业部 <> '' THEN '商用事业群'\\n            ELSE NULL\\n        END AS 上级名称,\\n        CASE\\n            WHEN 客户经理 <> '' THEN 客户经理\\n            WHEN 片区 <> '' THEN 片区\\n            WHEN 战区 <> '' THEN 战区\\n            WHEN 行业部 <> '' THEN 行业部\\n            ELSE '商用事业群'\\n        END AS 节点名称,\\n        CASE\\n            WHEN COALESCE(NULLIF(战区, ''), NULLIF(行业部, '')) LIKE '%行业部' THEN '行业线'\\n            WHEN COALESCE(NULLIF(战区, ''), NULLIF(行业部, '')) LIKE '%战区' THEN '区域线'\\n            ELSE '事业群层级'\\n        END AS 线,\\n        '商用事业群' AS 事业群,\\n        战区,\\n        片区,\\n        行业部,\\n        客户经理,\\n        总任务金额,\\n        年度开单金额\\n    FROM raw_data\\n),\\nsummarized_nodes AS (\\n    SELECT\\n        线,\\n        层级,\\n        上级名称,\\n        节点名称,\\n        MAX(事业群) AS 事业群,\\n        MAX(战区) AS 战区,\\n        MAX(片区) AS 片区,\\n        MAX(行业部) AS 行业部,\\n        MAX(客户经理) AS 客户经理,\\n        SUM(总任务金额) AS 总任务金额,\\n        SUM(年度开单金额) AS 年度开单金额\\n    FROM flattened_tree\\n    WHERE 节点名称 <> ''\\n    GROUP BY 线, 层级, 上级名称, 节点名称\\n)\\nSELECT\\n    线,\\n    层级,\\n    节点名称,\\n    上级名称,\\n    事业群,\\n    战区,\\n    片区,\\n    行业部,\\n    客户经理,\\n    总任务金额,\\n    年度开单金额,\\n    CASE WHEN 总任务金额 = 0 THEN 0 ELSE ROUND((年度开单金额 / 总任务金额) * 100, 2) END AS 达成率,\\n    ROUND(总任务金额 - 年度开单金额, 2) AS 剩余任务金额\\nFROM summarized_nodes\\n)\\nSELECT *\\nFROM 汇总结果\\nWHERE 层级 IN ('事业群', '战区', '行业部')\\nORDER BY\\n  CASE 层级 WHEN '事业群' THEN 0 WHEN '战区' THEN 1 WHEN '行业部' THEN 1 ELSE 9 END,\\n  达成率 DESC NULLS LAST,\\n  节点名称\\nLIMIT 100\\n) AS __datapulse_row_scope\\nWHERE ((to_jsonb(__datapulse_row_scope)->>'组织编码') IN ('28b5364e2f181bfg', 'gg9c5c9ce5c3faa9', '96a9gc77a35e5ee5', 'eb2685cfab3651df', '195c4ac5f864de57', '63aa3gb14a191aee', 'b8a3gda6d426a699', 'ef5bd91dc373gfbg') OR (to_jsonb(__datapulse_row_scope)->>'战区编码') IN ('28b5364e2f181bfg', 'gg9c5c9ce5c3faa9', '96a9gc77a35e5ee5', 'eb2685cfab3651df', '195c4ac5f864de57', '63aa3gb14a191aee', 'b8a3gda6d426a699', 'ef5bd91dc373gfbg') OR (to_jsonb(__datapulse_row_scope)->>'部门编码') IN ('28b5364e2f181bfg', 'gg9c5c9ce5c3faa9', '96a9gc77a35e5ee5', 'eb2685cfab3651df', '195c4ac5f864de57', '63aa3gb14a191aee', 'b8a3gda6d426a699', 'ef5bd91dc373gfbg') OR (to_jsonb(__datapulse_row_scope)->>'节点编码') IN ('28b5364e2f181bfg', 'gg9c5c9ce5c3faa9', '96a9gc77a35e5ee5', 'eb2685cfab3651df', '195c4ac5f864de57', '63aa3gb14a191aee', 'b8a3gda6d426a699', 'ef5bd91dc373gfbg') OR POSITION('28b5364e2f181bfg' IN COALESCE((to_jsonb(__datapulse_row_scope)->>'组织编码路径'), '')) > 0 OR POSITION('gg9c5c9ce5c3faa9' IN COALESCE((to_jsonb(__datapulse_row_scope)->>'组织编码路径'), '')) > 0 OR POSITION('96a9gc77a35e5ee5' IN COALESCE((to_jsonb(__datapulse_row_scope)->>'组织编码路径'), '')) > 0 OR POSITION('eb2685cfab3651df' IN COALESCE((to_jsonb(__datapulse_row_scope)->>'组织编码路径'), '')) > 0 OR POSITION('195c4ac5f864de57' IN COALESCE((to_jsonb(__datapulse_row_scope)->>'组织编码路径'), '')) > 0 OR POSITION('63aa3gb14a191aee' IN COALESCE((to_jsonb(__datapulse_row_scope)->>'组织编码路径'), '')) > 0 OR POSITION('b8a3gda6d426a699' IN COALESCE((to_jsonb(__datapulse