": 0.0, "线下任务_万元": 429.0, "线下实际_万元": 204.92, "新零售任务_万元": 0.0, "新零售实际_万元": 0.0, "燃气定制任务_万元": 6.0, "燃气定制实际_万元": 0.0}], "agent3_review": {"fixes": [], "risks": [], "approved": true, "final_sql": "WITH 字段提取 AS (\\n    SELECT\\n        id,\\n        COALESCE(NULLIF(TRIM(fields->>'事业群'), ''), '消费者事业群') AS 事业群,\\n        COALESCE(NULLIF(TRIM(fields->>'战区'), ''), '') AS 战区,\\n        COALESCE(NULLIF(TRIM(fields->>'城市战区'), ''), '') AS 城市战区,\\n        COALESCE(NULLIF(TRIM(fields->>'层级级别'), ''), '') AS 源层级,\\n        COALESCE(NULLIF(TRIM(fields->>'当前年'), ''), '2026') AS 当前年,\\n        NULLIF(regexp_replace(COALESCE(fields->>'总任务（金额）', ''), '[^0-9.-]', '', 'g'), '')::NUMERIC AS 总任务原值,\\n        NULLIF(regexp_replace(COALESCE(fields->>'年度开单金额', ''), '[^0-9.-]', '', 'g'), '')::NUMERIC AS 年度开单原值,\\n        NULLIF(regexp_replace(COALESCE(fields->>'线下（万）', ''), '[^0-9.-]', '', 'g'), '')::NUMERIC AS 线下任务万,\\n        NULLIF(regexp_replace(COALESCE(fields->>'新零售（万）', ''), '[^0-9.-]', '', 'g'), '')::NUMERIC AS 新零售任务万,\\n        NULLIF(regexp_replace(COALESCE(fields->>'燃气定制（万）', ''), '[^0-9.-]', '', 'g'), '')::NUMERIC AS 燃气定制任务万,\\n        NULLIF(regexp_replace(COALESCE(fields->>'地产（万）', ''), '[^0-9.-]', '', 'g'), '')::NUMERIC AS 地产任务万,\\n        NULLIF(regexp_replace(COALESCE(fields->>'线下-年度开单金额（万）', ''), '[^0-9.-]', '', 'g'), '')::NUMERIC AS 线下实际万,\\n        NULLIF(regexp_replace(COALESCE(fields->>'新零售-年度开单金额（万）', ''), '[^0-9.-]', '', 'g'), '')::NUMERIC AS 新零售实际万,\\n        NULLIF(regexp_replace(COALESCE(fields->>'燃气定制-年度开单金额（万）', ''), '[^0-9.-]', '', 'g'), '')::NUMERIC AS 燃气定制实际万,\\n        NULLIF(regexp_replace(COALESCE(fields->>'地产-年度开单金额（万）', ''), '[^0-9.-]', '', 'g'), '')::NUMERIC AS 地产实际万\\n    FROM public.feishu_tbl_alpha\\n    WHERE fields IS NOT NULL\\n),\\n标准行 AS (\\n    SELECT\\n        id,\\n        CASE\\n            WHEN 城市战区 <> '' THEN '城市战区'\\n            WHEN 战区 <> '' THEN '战区'\\n            ELSE '消费者事业群总体'\\n        END AS 层级,\\n        CASE\\n            WHEN 城市战区 <> '' THEN 城市战区\\n            WHEN 战区 <> '' THEN 战区\\n            ELSE 事业群\\n        END AS 节点名称,\\n        CASE\\n            WHEN 城市战区 <> '' THEN 战区\\n            WHEN 战区 <> '' THEN 事业群\\n            ELSE NULL\\n        END AS 上级名称,\\n        COALESCE(总任务原值, (COALESCE(线下任务万, 0) + COALESCE(新零售任务万, 0) + COALESCE(燃气定制任务万, 0) + COALESCE(地产任务万, 0)) * 10000, 0) AS 总任务金额,\\n        COALESCE(年度开单原值, (COALESCE(线下实际万, 0) + COALESCE(新零售实际万, 0) + COALESCE(燃气定制实际万, 0) + COALESCE(地产实际万, 0)) * 10000, 0) AS 年度开单金额,\\n        COALESCE(线下任务万, 0) AS 线下任务_万元,\\n        COALESCE(新零售任务万, 0) AS 新零售任务_万元,\\n        COALESCE(燃气定制任务万, 0) AS 燃气定制任务_万元,\\n        COALESCE(地产任务万, 0) AS 地产任务_万元,\\n        COALESCE(线下实际万, 0) AS 线下实际_万元,\\n        COALESCE(新零售实际万, 0) AS 新零售实际_万元,\\n        COALESCE(燃气定制实际万, 0) AS 燃气定制实际_万元,\\n        COALESCE(地产实际万, 0) AS 地产实际_万元\\n    FROM 字段提取\\n    WHERE 当前年 = '2026'\\n      AND (事业群 = '消费者事业群' OR 战区 <> '' OR 城市战区 <> '')\\n),\\n汇总结果 AS (\\n    SELECT\\n        '消费者经营链路' AS 线,\\n        '全部' AS 分析口径,\\n        层级,\\n        节点名称,\\n        上级名称,\\n        ROUND((总任务金额), 2) AS 总任务金额,\\n        ROUND((年度开单金额), 2) AS 年度开单金额,\\n        CASE WHEN (总任务金额) > 0 THEN ROUND((年度开单金额) / (总任务金额) * 100, 2) ELSE 0 END AS 达成率,\\n        ROUND(GREATEST((总任务金额) - (年度开单金额), 0), 2) AS 剩余任务金额,\\n        ROUND(线下任务_万元, 2) AS 线下任务_万元,\\n        ROUND(新零售任务_万元, 2) AS 新零售任务_万元,\\n        ROUND(燃气定制任务_万元, 2) AS 燃气定制任务_万元,\\n        ROUND(地产任务_万元, 2) AS 地产任务_万元,\\n        ROUND(线下实际_万元, 2) AS 线下实际_万元,\\n        ROUND(新零售实际_万元, 2) AS 新零售实际_万元,\\n        ROUND(燃气定制实际_万元, 2) AS 燃气定制实际_万元,\\n        ROUND(地产实际_万元, 2) AS 地产实际_万元\\n    FROM 标准行\\n    WHERE 节点名称 <> ''\\n      AND ((总任务金额) > 0 OR (年度开单金额) > 0)\\n)\\nSELECT *\\nFROM 汇总结果\\n\\nWHERE 节点名称 IN ('榕岭战区','下城市站','榕岭战区下城市站')\\n   OR 上级名称 IN ('榕岭战区','下城市站','榕岭战区下城市站')\\n\\nORDER BY\\n    CASE 层级 WHEN '消费者事业群总体' THEN 0 WHEN '战区' THEN 1 WHEN '城市战区' THEN 2 ELSE 9 END,\\n    上级名称 NULLS FIRST,\\n    达成率 DESC,\\n    节点名称\\nLIMIT 10000", "review_summary": "规则 SQL 已通过只读与字段字典校验，Agent3 不改写系统规则 SQL。"}}], "effective_question": "榕岭战区的业绩", "requires_confirmation": false, "confirmation_session_id": "", "conversation_session_id": ""}	2026-09-12 23:31:44.486551+08
85	qa	smart_chat_answer	info	智能问数结果	13800000001	演示管理员	business_admin	password	192.168.65.1	Python-urllib/3.13	POST	/api/smart-chat	200	52351	消费者事业群各战区业绩排名	[]	SELECT * FROM (\nWITH 源数据 AS (\n  SELECT\n    fields,\n    COALESCE(NULLIF(regexp_replace(fields ->> '总任务（金额）', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 总任务原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '年度开单金额', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 年度开单原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '线下', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 线下任务原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '线下-年度开单金额', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 线下实际原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '新零售', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 新零售任务原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '新零售-年度开单金额', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 新零售实际原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '燃气定制', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 燃气定制任务原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '燃气定制-年度开单金额', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 燃气定制实际原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '地产', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 地产任务原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '地产-年度开单金额', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 地产实际原值,\n    COALESCE(NULLIF(regexp_replace(fields ->> '总任务达成率', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 达成率原值\n  FROM public.feishu_tbl_alpha\n),\n标准结果 AS (\n  SELECT\n    '消费者事业群' AS 线,\n    CASE\n      WHEN NULLIF(fields ->> '战区', '') IS NULL THEN '消费者事业群总体'\n      WHEN NULLIF(fields ->> '城市战区', '') IS NULL THEN '战区'\n      ELSE '城市战区'\n    END AS 层级,\n    CASE\n      WHEN NULLIF(fields ->> '战区', '') IS NULL THEN '消费者事业群'\n      WHEN NULLIF(fields ->> '城市战区', '') IS NULL THEN fields ->> '战区'\n      ELSE fields ->> '城市战区'\n    END AS 节点名称,\n    CASE\n      WHEN NULLIF(fields ->> '战区', '') IS NULL THEN NULL\n      WHEN NULLIF(fields ->> '城市战区', '') IS NULL THEN '消费者事业群'\n      ELSE fields ->> '战区'\n    END AS 上级名称,\n    ROUND(总任务原值, 2) AS 总任务金额,\n    ROUND(年度开单原值, 2) AS 年度开单金额,\n    ROUND(CASE WHEN 总任务原值 > 0 THEN 年度开单原值 / 总任务原值 * 100 ELSE 达成率原值 END, 2) AS 达成率,\n    ROUND(GREATEST(总任务原值 - 年度开单原值, 0), 2) AS 剩余任务金额,\n    ROUND(线下任务原值, 2) AS 线下任务金额,\n    ROUND(线下实际原值, 2) AS 线下开单金额,\n    ROUND(新零售任务原值, 2) AS 新零售任务金额,\n    ROUND(新零售实际原值, 2) AS 新零售开单金额,\n    ROUND(燃气定制任务原值, 2) AS 燃气定制任务金额,\n    ROUND(燃气定制实际原值, 2) AS 燃气定制开单金额,\n    ROUND(地产任务原值, 2) AS 地产任务金额,\n    ROUND(地产实际原值, 2) AS 地产开单金额\n  FROM 源数据\n  WHERE 总任务原值 > 0\n)\nSELECT *\nFROM 标准结果\nWHERE 层级 = '战区'\nORDER BY 达成率 DESC, 年度开单金额 DESC, 节点名称\nLIMIT 100\n) AS __datapulse_row_scope\nWHERE ((to_jsonb(__datapulse_row_scope)->>'组织编码') IN ('7c38ff2d14dd5515', '1f5bc53566bfa5b2', '4c92717a393b3248', 'e26cc888231cb3c9', '1bbd2a36b2fb686f', '4b66949a1g2g1e8c', '196873fd1d2cfg85', '843a34aa6g3gg763', 'b45ddd151517eag6', 'e99798612e98b4d6', 'bg18ddb2efb2gf61', 'egg37cg26bafg5a9', 'aa34g4b218a28bgf', 'egcc258a8d9c811f') OR (to_jsonb(__datapulse_row_scope)->>'战区编码') IN ('7c38ff2d14dd5515', '1f5bc53566bfa5b2', '4c92717a393b3248', 'e26cc888231cb3c9', '1bbd2a36b2fb686f', '4b66949a1g2g1e8c', '196873fd1d2cfg85', '843a34aa6g3gg763', 'b45ddd151517eag6', 'e99798612e98b4d6', 'bg18ddb2efb2gf61', 'egg37cg26bafg5a9', 'aa34g4b218a28bgf', 'egcc258a8d9c811f') OR (to_jsonb(__datapulse_row_scope)->>'部门编码') IN ('7c38ff2d14dd5515', '1f5bc53566bfa5b2', '4c92717a393b3248', 'e26cc888231cb3c9', '1bbd2a36b2fb686f', '4b66949a1g2g1e8c', '196873fd1d2cfg85', '843a34aa6g3gg763', 'b45ddd151517eag6', 'e99798612e98b4d6', 'bg18ddb2efb2gf61', 'egg37cg26bafg5a9', 'aa34g4b218a28bgf', 'egcc258a8d9c811f') OR (to_jsonb(__datapulse_row_scope)->>'节点编码') IN ('7c38ff2d14dd5515', '1f5bc53566bfa5b2', '4c92717a393b3248', 'e26cc888231cb3c9', '1bbd2a36b2fb686f', '4b66949a1g2g1e8c', '196873fd1d2cfg85', '843a34aa6g3gg763', 'b45ddd151517eag6', 'e99798612e98b4d6', 'bg18ddb2efb2gf61', 'egg37cg26bafg5a9', 'aa34g4b218a28bgf', 'egcc258a8d9c811f') OR POSITION('7c38