数据 AS (\\n  SELECT\\n    fields,\\n    COALESCE(NULLIF(regexp_replace(fields ->> '总任务（金额）', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 总任务原值,\\n    COALESCE(NULLIF(regexp_replace(fields ->> '年度开单金额', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 年度开单原值,\\n    COALESCE(NULLIF(regexp_replace(fields ->> '线下', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 线下任务原值,\\n    COALESCE(NULLIF(regexp_replace(fields ->> '线下-年度开单金额', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 线下实际原值,\\n    COALESCE(NULLIF(regexp_replace(fields ->> '新零售', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 新零售任务原值,\\n    COALESCE(NULLIF(regexp_replace(fields ->> '新零售-年度开单金额', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 新零售实际原值,\\n    COALESCE(NULLIF(regexp_replace(fields ->> '燃气定制', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 燃气定制任务原值,\\n    COALESCE(NULLIF(regexp_replace(fields ->> '燃气定制-年度开单金额', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 燃气定制实际原值,\\n    COALESCE(NULLIF(regexp_replace(fields ->> '地产', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 地产任务原值,\\n    COALESCE(NULLIF(regexp_replace(fields ->> '地产-年度开单金额', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 地产实际原值,\\n    COALESCE(NULLIF(regexp_replace(fields ->> '总任务达成率', '[^0-9.-]', '', 'g'), ''), '0')::NUMERIC AS 达成率原值\\n  FROM public.feishu_tbl_alpha\\n),\\n标准结果 AS (\\n  SELECT\\n    '消费者事业群' AS 线,\\n    CASE\\n      WHEN NULLIF(fields ->> '战区', '') IS NULL THEN '消费者事业群总体'\\n      WHEN NULLIF(fields ->> '城市战区', '') IS NULL THEN '战区'\\n      ELSE '城市战区'\\n    END AS 层级,\\n    CASE\\n      WHEN NULLIF(fields ->> '战区', '') IS NULL THEN '消费者事业群'\\n      WHEN NULLIF(fields ->> '城市战区', '') IS NULL THEN fields ->> '战区'\\n      ELSE fields ->> '城市战区'\\n    END AS 节点名称,\\n    CASE\\n      WHEN NULLIF(fields ->> '战区', '') IS NULL THEN NULL\\n      WHEN NULLIF(fields ->> '城市战区', '') IS NULL THEN '消费者事业群'\\n      ELSE fields ->> '战区'\\n    END AS 上级名称,\\n    ROUND(总任务原值, 2) AS 总任务金额,\\n    ROUND(年度开单原值, 2) AS 年度开单金额,\\n    ROUND(CASE WHEN 总任务原值 > 0 THEN 年度开单原值 / 总任务原值 * 100 ELSE 达成率原值 END, 2) AS 达成率,\\n    ROUND(GREATEST(总任务原值 - 年度开单原值, 0), 2) AS 剩余任务金额,\\n    ROUND(线下任务原值, 2) AS 线下任务金额,\\n    ROUND(线下实际原值, 2) AS 线下开单金额,\\n    ROUND(新零售任务原值, 2) AS 新零售任务金额,\\n    ROUND(新零售实际原值, 2) AS 新零售开单金额,\\n    ROUND(燃气定制任务原值, 2) AS 燃气定制任务金额,\\n    ROUND(燃气定制实际原值, 2) AS 燃气定制开单金额,\\n    ROUND(地产任务原值, 2) AS 地产任务金额,\\n    ROUND(地产实际原值, 2) AS 地产开单金额\\n  FROM 源数据\\n  WHERE 总任务原值 > 0\\n)\\nSELECT *\\nFROM 标准结果\\nWHERE 层级 = '战区'\\nORDER BY 达成率 DESC, 年度开单金额 DESC, 节点名称\\nLIMIT 100\\n) AS __datapulse_row_scope\\nWHERE ((to_jsonb(__datapulse_row_scope)->>'组织编码') IN ('7c38ff2d14dd5515', '1f5bc53566bfa5b2', '4c92717a393b3248', 'e26cc888231cb3c9', '1bbd2a36b2fb686f', '4b66949a1g2g1e8c', '196873fd1d2cfg85', '843a34aa6g3gg763', 'b45ddd151517eag6', 'e99798612e98b4d6', 'bg18ddb2efb2gf61', 'egg37cg26bafg5a9', 'aa34g4b218a28bgf', 'egcc258a8d9c811f') OR (to_jsonb(__datapulse_row_scope)->>'战区编码') IN ('7c38ff2d14dd5515', '1f5bc53566bfa5b2', '4c92717a393b3248', 'e26cc888231cb3c9', '1bbd2a36b2fb686f', '4b66949a1g2g1e8c', '196873fd1d2cfg85', '843a34aa6g3gg763', 'b45ddd151517eag6', 'e99798612e98b4d6', 'bg18ddb2efb2gf61', 'egg37cg26bafg5a9', 'aa34g4b218a28bgf', 'egcc258a8d9c811f') OR (to_jsonb(__datapulse_row_scope)->>'部门编码') IN ('7c38ff2d14dd5515', '1f5bc53566bfa5b2', '4c92717a393b3248', 'e26cc888231cb3c9', '1bbd2a36b2fb686f', '4b66949a1g2g1e8c', '196873fd1d2cfg85', '843a34aa6g3gg763', 'b45ddd151517eag6', 'e99798612e98b4d6', 'bg18ddb2efb2gf61', 'egg37cg26bafg5a9', 'aa34g4b218a28bgf', 'egcc258a8d9c811f') OR (to_jsonb(__datapulse_row_scope)->>'节点编码') IN ('7c38ff2d14dd5515', '1f5bc53566bfa5b2', '4c92717a393b3248', 'e26cc888231cb3c9', '1bbd2a36b2fb686f', '4b66949a1g2g1e8c', '196873fd1d2cfg85', '843a34aa6g3gg763', 'b45ddd151517eag6', 'e99798612e98b4d6', 'bg18ddb2efb2gf61', 'egg37cg26bafg5a9', 'aa34g4b218a28bgf', 'egcc258a8d9c811f') OR POSITION('7c38ff2d14dd5515' IN COALESCE((to_jsonb(__datapulse_row_scope)->>'组织编码路径'), '')) > 0 OR POSITION('1f5bc53566bfa5b2' IN COALESCE((t