n        ''),\\n      '2026') = '2026'\\n  GROUP BY 1,\\n    2,\\n    3,\\n    4 ),\\n  flattened_tree AS (\\n  SELECT CASE WHEN 客户经理 <> '' THEN '客户经理' WHEN 片区 <> '' THEN '片区' WHEN 战区 <> ''\\n    AND 战区 LIKE '%行业部' THEN '行业部' WHEN 行业部 <> '' THEN '行业部' WHEN 战区 <> '' THEN '战区' ELSE '事业群' END AS 层级,\\n    CASE WHEN 客户经理 <> '' THEN COALESCE(NULLIF(片区,\\n        ''),\\n      NULLIF(行业部,\\n        ''),\\n      NULLIF(战区,\\n        ''),\\n      '商用事业群') WHEN 片区 <> '' THEN NULLIF(战区,\\n      '') WHEN 战区 <> ''\\n    OR 行业部 <> '' THEN '商用事业群' ELSE NULL END AS 上级名称,\\n    CASE WHEN 客户经理 <> '' THEN 客户经理 WHEN 片区 <> '' THEN 片区 WHEN 战区 <> '' THEN 战区 WHEN 行业部 <> '' THEN 行业部 ELSE '商用事业群' END AS 节点名称,\\n    CASE WHEN COALESCE(NULLIF(战区,\\n        ''),\\n      NULLIF(行业部,\\n        '')) LIKE '%行业部' THEN '行业线' WHEN COALESCE(NULLIF(战区,\\n        ''),\\n      NULLIF(行业部,\\n        '')) LIKE '%战区' THEN '区域线' ELSE '事业群层级' END AS 线,\\n    总任务金额,\\n    年度开单金额\\n  FROM raw_data ),\\n  summarized_nodes AS (\\n  SELECT 线,\\n    层级,\\n    上级名称,\\n    节点名称,\\n    SUM(总任务金额) AS 总任务金额,\\n    SUM(年度开单金额) AS 年度开单金额\\n  FROM flattened_tree\\n  WHERE 节点名称 <> ''\\n  GROUP BY 线,\\n    层级,\\n    上级名称,\\n    节点名称 )\\nSELECT 线,\\n  层级,\\n  节点名称,\\n  上级名称,\\n  总任务金额,\\n  年度开单金额,\\n  CASE WHEN 总任务金额 = 0 THEN 0 ELSE ROUND((年度开单金额 / 总任务金额) * 100,\\n    2) END AS 达成率,\\n  ROUND(总任务金额 - 年度开单金额,\\n    2) AS 剩余任务金额\\nFROM summarized_nodes )\\n\\n-- 这里只查【某个业务员】\\nSELECT *\\nFROM 汇总结果\\nWHERE 层级 = '客户经理' \\n  AND 节点名称 = '钟自蹊'  -- 把张三改成你要查的业务员名字\\nORDER BY 节点名称\\n) AS __datapulse_row_scope\\nWHERE ((to_jsonb(__datapulse_row_scope)->>'组织编码') IN ('28b5364e2f181bfg', 'gg9c5c9ce5c3faa9', '96a9gc77a35e5ee5', 'eb2685cfab3651df', '195c4ac5f864de57', '63aa3gb14a191aee', 'b8a3gda6d426a699', 'ef5bd91dc373gfbg') OR (to_jsonb(__datapulse_row_scope)->>'战区编码') IN ('28b5364e2f181bfg', 'gg9c5c9ce5c3faa9', '96a9gc77a35e5ee5', 'eb2685cfab3651df', '195c4ac5f864de57', '63aa3gb14a191aee', 'b8a3gda6d426a699', 'ef5bd91dc373gfbg') OR (to_jso